mapper.select:
SELECT id, sku, merchant_id, product_name, price, stock_quantity, sold_quantity, version, created_at, updated_at
FROM product_inventory
WHERE merchant_id = #{merchantId} AND sku = #{sku}

mapper.update:
UPDATE product_inventory
SET stock_quantity = stock_quantity - #{quantity},
    sold_quantity = sold_quantity + #{quantity},
    version = version + 1,
    updated_at = NOW()
WHERE merchant_id = #{merchantId}
  AND sku = #{sku}
  AND version = #{version}
  AND stock_quantity >= #{quantity}

UPDATE product_inventory
SET stock_quantity = stock_quantity + #{quantity},
    sold_quantity = sold_quantity - #{quantity},
    version = version + 1,
    updated_at = NOW()
WHERE merchant_id = #{merchantId}
  AND sku = #{sku}
  AND version = #{version}
